import * as http from "http"

// Client HTTP Request helper
export function makeClientRequest(
  port: number,
  pathname: string,
  method: "GET" | "POST",
  bodyParams: Record<string, unknown> = {}
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
): Promise<any> {
  return new Promise((resolve, reject) => {
    const serial = typeof bodyParams.serial === "string" ? bodyParams.serial : undefined
    const query = method === "GET" && serial ? `?serial=${encodeURIComponent(serial)}` : ""
    const options: http.RequestOptions = {
      hostname: "127.0.0.1",
      port,
      path: `${pathname}${query}`,
      method,
      headers: method === "POST" ? { "Content-Type": "application/json" } : {}
    }

    const req = http.request(options, (res) => {
      if (res.headers["content-type"]?.includes("image/")) {
        const chunks: Buffer[] = []
        res.on("data", chunk => chunks.push(chunk))
        res.on("end", () => resolve({ type: "binary", mimeType: res.headers["content-type"], data: Buffer.concat(chunks) }))
        return
      }

      let data = ""
      res.on("data", chunk => data += chunk)
      res.on("end", () => {
        try {
          resolve(JSON.parse(data))
        } catch {
          resolve(data)
        }
      })
    })

    req.on("error", err => reject(err))
    if (method === "POST") {
      req.write(JSON.stringify(bodyParams))
    }
    req.end()
  })
}

// Check if daemon is active
export function checkDaemonActive(port: number): Promise<boolean> {
  return new Promise((resolve) => {
    const socket = new http.ClientRequest({
      hostname: "127.0.0.1",
      port,
      path: "/device/list",
      method: "GET",
      timeout: 1000
    })
    socket.on("response", () => resolve(true))
    socket.on("error", () => resolve(false))
    socket.on("timeout", () => resolve(false))
    socket.end()
  })
}

