import * as fs from "fs"
import * as path from "path"

export interface WorkspaceConfig {
  serial?: string
  port?: number
  maxSize?: number
  maxFps?: number
  videoBitRate?: number
  videoEncoder?: string
}

export function loadWorkspaceConfig(startDir: string = process.cwd()): WorkspaceConfig {
  let currentDir = startDir

  while (true) {
    const rcPath = path.join(currentDir, ".scrcpyrc")
    if (fs.existsSync(rcPath)) {
      try {
        const content = fs.readFileSync(rcPath, "utf8")
        const parsed = JSON.parse(content)
        const config: WorkspaceConfig = {}
        if (parsed.serial && typeof parsed.serial === "string") {
          config.serial = parsed.serial
        }
        if (parsed.port !== undefined) {
          const portNum = parseInt(parsed.port, 10)
          if (!isNaN(portNum)) {
            config.port = portNum
          }
        }
        const parsedMaxSize = parsed.maxSize !== undefined ? parsed.maxSize : parsed.max_size
        if (parsedMaxSize !== undefined) {
          const val = parseInt(parsedMaxSize, 10)
          if (!isNaN(val)) {
            config.maxSize = val
          }
        }
        const parsedMaxFps = parsed.maxFps !== undefined
          ? parsed.maxFps
          : parsed.max_fps
        if (parsedMaxFps !== undefined) {
          const val = parseInt(parsedMaxFps, 10)
          if (!isNaN(val)) {
            config.maxFps = val
          }
        }
        const parsedVideoBitRate = parsed.videoBitRate !== undefined
          ? parsed.videoBitRate
          : parsed.video_bit_rate
        if (parsedVideoBitRate !== undefined) {
          const val = parseInt(parsedVideoBitRate, 10)
          if (!isNaN(val)) {
            config.videoBitRate = val
          }
        }
        const parsedVideoEncoder = parsed.videoEncoder !== undefined
          ? parsed.videoEncoder
          : parsed.video_encoder
        if (parsedVideoEncoder && typeof parsedVideoEncoder === "string") {
          config.videoEncoder = parsedVideoEncoder
        }
        if (
          config.serial ||
          config.port !== undefined ||
          config.maxSize !== undefined ||
          config.maxFps !== undefined ||
          config.videoBitRate !== undefined ||
          config.videoEncoder !== undefined
        ) {
          return config
        }
      } catch {
        // Ignore error and continue
      }
    }

    const envPath = path.join(currentDir, ".env")
    if (fs.existsSync(envPath)) {
      try {
        const content = fs.readFileSync(envPath, "utf8")
        const lines = content.split(/\r?\n/)
        const config: WorkspaceConfig = {}
        for (const line of lines) {
          const trimmed = line.trim()
          if (!trimmed || trimmed.startsWith("#")) continue
          const index = trimmed.indexOf("=")
          if (index === -1) continue
          const key = trimmed.substring(0, index).trim()
          const val = trimmed.substring(index + 1).trim()
          const cleanVal = val.replace(/^["']|["']$/g, "")

          if (key === "ANDROID_SERIAL") {
            config.serial = cleanVal
          } else if (key === "SCRCPY_PORT" || key === "PORT") {
            const portNum = parseInt(cleanVal, 10)
            if (!isNaN(portNum)) {
              config.port = portNum
            }
          } else if (key === "SCRCPY_MAX_SIZE" || key === "MAX_SIZE") {
            const sizeVal = parseInt(cleanVal, 10)
            if (!isNaN(sizeVal)) {
              config.maxSize = sizeVal
            }
          } else if (key === "SCRCPY_MAX_FPS" || key === "MAX_FPS") {
            const fpsVal = parseInt(cleanVal, 10)
            if (!isNaN(fpsVal)) {
              config.maxFps = fpsVal
            }
          } else if (key === "SCRCPY_VIDEO_BIT_RATE" || key === "VIDEO_BIT_RATE") {
            const rateVal = parseInt(cleanVal, 10)
            if (!isNaN(rateVal)) {
              config.videoBitRate = rateVal
            }
          } else if (key === "SCRCPY_VIDEO_ENCODER" || key === "VIDEO_ENCODER") {
            config.videoEncoder = cleanVal
          }
        }
        if (
          config.serial ||
          config.port !== undefined ||
          config.maxSize !== undefined ||
          config.maxFps !== undefined ||
          config.videoBitRate !== undefined ||
          config.videoEncoder !== undefined
        ) {
          return config
        }
      } catch {
        // Ignore error and continue
      }
    }

    const parentDir = path.dirname(currentDir)
    if (parentDir === currentDir) {
      break
    }
    currentDir = parentDir
  }

  return {}
}
