import { execFileSync } from "child_process"
import * as fs from "fs"
import * as path from "path"
import { SCRCPY_SERVER_VERSION } from "../constants.js"
import { getPlatformAsset, type PlatformAssetInfo } from "./client.js"

export interface RuntimeVersionInfo {
  version: string
  clientPath: string | null
  serverPath: string | null
  updatedAt?: string
}

export function getRuntimeCacheDir(): string {
  const homeDir = process.env.HOME || process.env.USERPROFILE || ""
  const cacheBase = process.env.XDG_CACHE_HOME ||
    (process.env.LOCALAPPDATA
      ? path.join(process.env.LOCALAPPDATA, "scrcpy-cli")
      : path.join(homeDir, ".cache", "scrcpy-cli"))
  return path.join(cacheBase, "runtime")
}

export function getRuntimeVersionConfigPath(): string {
  if (process.env.SCRCPY_RUNTIME_CONFIG) {
    return process.env.SCRCPY_RUNTIME_CONFIG
  }
  return path.join(getRuntimeCacheDir(), "version.json")
}

export function getRuntimeVersionInfo(): RuntimeVersionInfo | null {
  const configPath = getRuntimeVersionConfigPath()
  if (!fs.existsSync(configPath)) {
    return null
  }
  try {
    const data = JSON.parse(fs.readFileSync(configPath, "utf8")) as RuntimeVersionInfo
    if (data.version && data.serverPath && fs.existsSync(data.serverPath)) {
      return data
    }
  } catch {
    // Ignore corrupt config
  }
  return null
}

export async function fetchLatestScrcpyVersion(): Promise<string> {
  const url = "https://api.github.com/repos/Genymobile/scrcpy/releases/latest"
  try {
    const res = await fetch(url, {
      headers: {
        "User-Agent": "scrcpy-cli",
        "Accept": "application/vnd.github.v3+json",
      },
    })
    if (!res.ok) {
      throw new Error(`GitHub API returned HTTP ${res.status}: ${res.statusText}`)
    }
    const data = await res.json() as { tag_name?: string }
    if (data.tag_name) {
      return data.tag_name.replace(/^v/, "")
    }
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : String(err)
    console.error(`[updater] Could not query latest GitHub release: ${msg}`)
  }
  return SCRCPY_SERVER_VERSION
}

async function downloadFile(url: string, dest: string): Promise<Buffer> {
  const res = await fetch(url, { redirect: "follow" })
  if (!res.ok) {
    throw new Error(`Failed to download ${url} (HTTP ${res.status}: ${res.statusText})`)
  }
  const arrayBuffer = await res.arrayBuffer()
  const buffer = Buffer.from(arrayBuffer)
  if (buffer.length < 1024) {
    throw new Error(`Downloaded file too small (${buffer.length} bytes)`)
  }
  fs.writeFileSync(dest, buffer)
  return buffer
}

function extractArchive(archivePath: string, destDir: string, asset: PlatformAssetInfo): void {
  if (!fs.existsSync(destDir)) {
    fs.mkdirSync(destDir, { recursive: true })
  }

  const tempExtractDir = path.join(destDir, "_temp_extract")
  if (fs.existsSync(tempExtractDir)) {
    fs.rmSync(tempExtractDir, { recursive: true, force: true })
  }
  fs.mkdirSync(tempExtractDir, { recursive: true })

  try {
    if (asset.type === "zip") {
      if (process.platform === "win32") {
        execFileSync("tar", ["-xf", archivePath, "-C", tempExtractDir])
      } else {
        execFileSync("unzip", ["-q", "-o", archivePath, "-d", tempExtractDir])
      }
    } else {
      execFileSync("tar", ["-xzf", archivePath, "-C", tempExtractDir])
    }

    const subDirPath = path.join(tempExtractDir, asset.subDir)
    const sourceDir = fs.existsSync(subDirPath) ? subDirPath : tempExtractDir

    for (const item of fs.readdirSync(sourceDir)) {
      const srcItem = path.join(sourceDir, item)
      const dstItem = path.join(destDir, item)
      if (fs.existsSync(dstItem)) {
        fs.rmSync(dstItem, { recursive: true, force: true })
      }
      fs.cpSync(srcItem, dstItem, { recursive: true })
    }
  } finally {
    if (fs.existsSync(tempExtractDir)) {
      fs.rmSync(tempExtractDir, { recursive: true, force: true })
    }
  }
}

export async function updateScrcpy(
  targetVersion?: string
): Promise<{ version: string; clientPath: string | null; serverPath: string }> {
  const version = targetVersion
    ? targetVersion.replace(/^v/, "")
    : await fetchLatestScrcpyVersion()

  const runtimeDir = getRuntimeCacheDir()
  if (!fs.existsSync(runtimeDir)) {
    fs.mkdirSync(runtimeDir, { recursive: true })
  }

  const versionDir = path.join(runtimeDir, `v${version}`)
  if (!fs.existsSync(versionDir)) {
    fs.mkdirSync(versionDir, { recursive: true })
  }

  let clientPath: string | null = null
  let serverPath = path.join(versionDir, "scrcpy-server")

  const asset = getPlatformAsset(version)
  if (asset) {
    const clientUrl = `https://github.com/Genymobile/scrcpy/releases/download/v${version}/${asset.name}`
    const tempArchive = path.join(versionDir, `_download_${asset.name}`)

    console.log(`[scrcpy update] Downloading scrcpy bundle v${version} (${asset.name})...`)
    try {
      await downloadFile(clientUrl, tempArchive)
      console.log(`[scrcpy update] Extracting scrcpy bundle...`)
      extractArchive(tempArchive, versionDir, asset)
      const expectedBin = path.join(versionDir, asset.binName)
      if (fs.existsSync(expectedBin)) {
        clientPath = expectedBin
      }
      if (fs.existsSync(path.join(versionDir, "scrcpy-server"))) {
        serverPath = path.join(versionDir, "scrcpy-server")
      }
    } finally {
      if (fs.existsSync(tempArchive)) {
        fs.rmSync(tempArchive, { force: true })
      }
    }
  } else {
    // Fallback for architectures without platform package: download server only
    const serverUrl = `https://github.com/Genymobile/scrcpy/releases/download/v${version}/scrcpy-server-v${version}`
    console.log(`[scrcpy update] Downloading scrcpy-server v${version}...`)
    await downloadFile(serverUrl, serverPath)
  }

  // Save runtime configuration
  const info: RuntimeVersionInfo = {
    version,
    clientPath,
    serverPath,
    updatedAt: new Date().toISOString(),
  }

  fs.writeFileSync(getRuntimeVersionConfigPath(), JSON.stringify(info, null, 2), "utf8")
  console.log(`[scrcpy update] Successfully updated scrcpy to v${version}`)

  return { version, clientPath, serverPath }
}
