import { spawn, execFileSync, type ChildProcess } from "child_process"
import * as fs from "fs"
import * as path from "path"
import { fileURLToPath } from "url"
import { SCRCPY_SERVER_VERSION } from "../constants.js"
import { getRuntimeVersionInfo } from "./updater.js"

export interface PlatformAssetInfo {
  name: string
  type: "zip" | "tar.gz"
  binName: string
  subDir: string
}

export function getPlatformAsset(
  version: string = SCRCPY_SERVER_VERSION
): PlatformAssetInfo | null {
  const platform = process.platform
  const arch = process.arch

  if (platform === "win32") {
    return {
      name: `scrcpy-win64-v${version}.zip`,
      type: "zip",
      binName: "scrcpy.exe",
      subDir: `scrcpy-win64-v${version}`,
    }
  } else if (platform === "darwin") {
    const isArm = arch === "arm64"
    const name = isArm
      ? `scrcpy-macos-aarch64-v${version}.tar.gz`
      : `scrcpy-macos-x86_64-v${version}.tar.gz`
    return {
      name,
      type: "tar.gz",
      binName: "scrcpy",
      subDir: isArm ? `scrcpy-macos-aarch64-v${version}` : `scrcpy-macos-x86_64-v${version}`,
    }
  } else if (platform === "linux") {
    return {
      name: `scrcpy-linux-x86_64-v${version}.tar.gz`,
      type: "tar.gz",
      binName: "scrcpy",
      subDir: `scrcpy-linux-x86_64-v${version}`,
    }
  }
  return null
}

export function getBundledClientPaths(): string[] {
  const baseDir = import.meta.dirname || path.dirname(fileURLToPath(import.meta.url))
  const binName = process.platform === "win32" ? "scrcpy.exe" : "scrcpy"
  const relativeDirs = [
    path.resolve(baseDir, "../vendor/scrcpy"),
    path.resolve(baseDir, "../../vendor/scrcpy"),
    path.resolve(baseDir, "../../../vendor/scrcpy"),
    path.resolve(baseDir, "./vendor/scrcpy"),
    path.resolve(process.cwd(), "vendor/scrcpy"),
    path.resolve(baseDir, "../vendor"),
    path.resolve(baseDir, "../../vendor"),
    path.resolve(baseDir, "../../../vendor"),
    path.resolve(baseDir, "./vendor"),
    path.resolve(process.cwd(), "vendor"),
    path.resolve(baseDir),
  ]

  const paths: string[] = []
  for (const dir of relativeDirs) {
    paths.push(path.join(dir, binName))
  }
  return paths
}

export function getCacheClientDir(version: string = SCRCPY_SERVER_VERSION): string {
  const homeDir = process.env.HOME || process.env.USERPROFILE || ""
  const cacheBase = process.env.XDG_CACHE_HOME ||
    (process.env.LOCALAPPDATA
      ? path.join(process.env.LOCALAPPDATA, "scrcpy-cli")
      : path.join(homeDir, ".cache", "scrcpy-cli"))
  return path.join(cacheBase, `client-v${version}`)
}

export function findScrcpyClient(): string | null {
  const envPath = process.env.SCRCPY_PATH || process.env.SCRCPY_BIN
  if (envPath && fs.existsSync(envPath)) {
    return envPath
  }

  for (const p of getBundledClientPaths()) {
    if (fs.existsSync(p)) {
      return p
    }
  }

  const runtimeInfo = getRuntimeVersionInfo()
  if (runtimeInfo?.clientPath && fs.existsSync(runtimeInfo.clientPath)) {
    return runtimeInfo.clientPath
  }

  const binName = process.platform === "win32" ? "scrcpy.exe" : "scrcpy"
  const cacheDir = getCacheClientDir()
  const cachedBin = path.join(cacheDir, binName)
  if (fs.existsSync(cachedBin)) {
    return cachedBin
  }

  return null
}

function extractArchive(archivePath: string, destDir: string, asset: PlatformAssetInfo): void {
  if (!fs.existsSync(destDir)) {
    fs.mkdirSync(destDir, { recursive: true })
  }

  const tempExtractDir = path.join(destDir, "_temp_extract")
  if (fs.existsSync(tempExtractDir)) {
    fs.rmSync(tempExtractDir, { recursive: true, force: true })
  }
  fs.mkdirSync(tempExtractDir, { recursive: true })

  try {
    if (asset.type === "zip") {
      if (process.platform === "win32") {
        execFileSync("tar", ["-xf", archivePath, "-C", tempExtractDir])
      } else {
        execFileSync("unzip", ["-q", "-o", archivePath, "-d", tempExtractDir])
      }
    } else {
      execFileSync("tar", ["-xzf", archivePath, "-C", tempExtractDir])
    }

    const subDirPath = path.join(tempExtractDir, asset.subDir)
    const sourceDir = fs.existsSync(subDirPath) ? subDirPath : tempExtractDir

    for (const item of fs.readdirSync(sourceDir)) {
      const srcItem = path.join(sourceDir, item)
      const dstItem = path.join(destDir, item)
      if (fs.existsSync(dstItem)) {
        fs.rmSync(dstItem, { recursive: true, force: true })
      }
      fs.cpSync(srcItem, dstItem, { recursive: true })
    }
  } finally {
    if (fs.existsSync(tempExtractDir)) {
      fs.rmSync(tempExtractDir, { recursive: true, force: true })
    }
  }
}

export async function ensureScrcpyClient(
  version: string = SCRCPY_SERVER_VERSION
): Promise<string> {
  const existing = findScrcpyClient()
  if (existing) {
    return existing
  }

  const asset = getPlatformAsset(version)
  if (!asset) {
    throw new Error(
      `No prebuilt scrcpy client binary available for platform ${process.platform}/${process.arch}`
    )
  }

  const cacheDir = getCacheClientDir(version)
  const targetBin = path.join(cacheDir, asset.binName)

  if (fs.existsSync(targetBin)) {
    return targetBin
  }

  const url = `https://github.com/Genymobile/scrcpy/releases/download/v${version}/${asset.name}`
  const tempArchive = path.join(cacheDir, `_download_${asset.name}`)

  console.error(`[scrcpy] Downloading scrcpy client v${version} (${asset.name})...`)

  try {
    if (!fs.existsSync(cacheDir)) {
      fs.mkdirSync(cacheDir, { recursive: true })
    }

    const res = await fetch(url, { redirect: "follow" })
    if (!res.ok) {
      throw new Error(`HTTP ${res.status}: ${res.statusText}`)
    }
    const arrayBuffer = await res.arrayBuffer()
    const buffer = Buffer.from(arrayBuffer)
    if (buffer.length < 1024) {
      throw new Error(`File size unexpectedly small (${buffer.length} bytes)`)
    }
    fs.writeFileSync(tempArchive, buffer)

    console.error(`[scrcpy] Extracting scrcpy client to ${cacheDir}...`)
    extractArchive(tempArchive, cacheDir, asset)
    console.error(`[scrcpy] Successfully set up scrcpy client at ${targetBin}`)

    return targetBin
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : String(error)
    throw new Error(
      `scrcpy client not found and automated download failed: ${message}. ` +
      `Please set SCRCPY_PATH environment variable or install scrcpy.`,
      { cause: error }
    )
  } finally {
    if (fs.existsSync(tempArchive)) {
      fs.rmSync(tempArchive, { force: true })
    }
  }
}

export interface LaunchClientOptions {
  serial?: string
  args?: string[]
  detached?: boolean
  serverPath?: string
}

export async function launchScrcpyClient(options: LaunchClientOptions = {}): Promise<ChildProcess> {
  const { serial, args = [], detached = true, serverPath } = options
  const clientPath = await ensureScrcpyClient()

  const scrcpyArgs: string[] = []
  if (serial) {
    scrcpyArgs.push("-s", serial)
  }

  scrcpyArgs.push(...args)

  const clientDir = path.dirname(clientPath)

  let resolvedServer: string | undefined = serverPath
  if (!resolvedServer) {
    const clientServer = path.join(clientDir, "scrcpy-server")
    const clientServerJar = path.join(clientDir, "scrcpy-server.jar")
    if (fs.existsSync(clientServer)) {
      resolvedServer = clientServer
    } else if (fs.existsSync(clientServerJar)) {
      resolvedServer = clientServerJar
    } else {
      const runtimeInfo = getRuntimeVersionInfo()
      if (runtimeInfo?.serverPath && fs.existsSync(runtimeInfo.serverPath)) {
        resolvedServer = runtimeInfo.serverPath
      } else {
        const envServer = process.env.SCRCPY_SERVER_PATH
        if (envServer && fs.existsSync(envServer)) {
          resolvedServer = envServer
        }
      }
    }
  }

  const childEnv: NodeJS.ProcessEnv = {
    ...process.env,
    PATH: `${clientDir}${path.delimiter}${process.env.PATH || ""}`,
  }

  if (resolvedServer) {
    childEnv.SCRCPY_SERVER_PATH = resolvedServer
  } else {
    delete childEnv.SCRCPY_SERVER_PATH
  }

  const child = spawn(clientPath, scrcpyArgs, {
    detached,
    stdio: detached ? "ignore" : "inherit",
    cwd: clientDir,
    env: childEnv,
  })

  if (detached) {
    child.unref()
  }

  return child
}
