import { resolveKeycode } from "../utils/keycodes.js"

export const ACTION_COMMANDS = new Set([
  "tap",
  "swipe",
  "write",
  "key",
  "scroll",
  "screenshot",
  "ui-dump",
  "clipboard-get",
  "clipboard-set",
  "app-start",
  "app-stop",
  "app-list",
  "device-info",
  "device-list",
])

export function validateActionCommand(cmd: string, args: string[]): void {
  if (!ACTION_COMMANDS.has(cmd)) {
    throw new Error(`Unsupported direct command: ${cmd}`)
  }

  if (cmd === "key") {
    resolveKeycode(args[0])
  }
}
