import { spawn, execSync } from "child_process"
import * as fs from "fs"
import * as path from "path"
import * as net from "net"
import { fileURLToPath } from "url"
import { execAdb, getAdbPath } from "../adb.js"
import { SCRCPY_SERVER_PATH_LOCAL, SCRCPY_SERVER_VERSION } from "../constants.js"
import { getRuntimeVersionInfo } from "./updater.js"
import type { ScrcpySessionOptions } from "./types.js"

export function getBundledServerPaths(): string[] {
  const baseDir = import.meta.dirname || path.dirname(fileURLToPath(import.meta.url))
  const filenames = ["scrcpy-server.jar", "scrcpy-server"]
  const relativeDirs = [
    path.resolve(baseDir, "../vendor/scrcpy"),
    path.resolve(baseDir, "../../vendor/scrcpy"),
    path.resolve(baseDir, "../../../vendor/scrcpy"),
    path.resolve(baseDir, "./vendor/scrcpy"),
    path.resolve(process.cwd(), "vendor/scrcpy"),
    path.resolve(baseDir, "../vendor"),
    path.resolve(baseDir, "../../vendor"),
    path.resolve(baseDir, "../../../vendor"),
    path.resolve(baseDir, "./vendor"),
    path.resolve(process.cwd(), "vendor"),
    path.resolve(baseDir),
  ]

  const paths: string[] = []
  for (const dir of relativeDirs) {
    for (const name of filenames) {
      paths.push(path.join(dir, name))
    }
  }
  return paths
}

export function getCacheServerPath(version: string = SCRCPY_SERVER_VERSION): string {
  const homeDir = process.env.HOME || process.env.USERPROFILE || ""
  const cacheBase = process.env.XDG_CACHE_HOME ||
    (process.env.LOCALAPPDATA
      ? path.join(process.env.LOCALAPPDATA, "scrcpy-cli")
      : path.join(homeDir, ".cache", "scrcpy-cli"))
  return path.join(cacheBase, `scrcpy-server-v${version}.jar`)
}

export function findScrcpyServer(): string | null {
  const envPath = process.env.SCRCPY_SERVER_PATH
  if (envPath && fs.existsSync(envPath)) {
    return envPath
  }

  for (const p of getBundledServerPaths()) {
    if (fs.existsSync(p)) {
      return p
    }
  }

  const runtimeInfo = getRuntimeVersionInfo()
  if (runtimeInfo?.serverPath && fs.existsSync(runtimeInfo.serverPath)) {
    return runtimeInfo.serverPath
  }

  const cachePath = getCacheServerPath()
  if (fs.existsSync(cachePath)) {
    return cachePath
  }

  const homeDir = process.env.HOME || process.env.USERPROFILE
  const commonPaths: string[] = [
    "/usr/local/share/scrcpy/scrcpy-server",
    "/usr/share/scrcpy/scrcpy-server",
  ]

  if (homeDir) {
    commonPaths.unshift(path.join(homeDir, ".local", "share", "scrcpy", "scrcpy-server"))
  }

  for (const p of commonPaths) {
    if (fs.existsSync(p)) {
      return p
    }
  }

  return null
}

export async function ensureScrcpyServer(
  version: string = SCRCPY_SERVER_VERSION
): Promise<string> {
  const existing = findScrcpyServer()
  if (existing) {
    return existing
  }

  const cachePath = getCacheServerPath(version)
  const cacheDir = path.dirname(cachePath)
  if (!fs.existsSync(cacheDir)) {
    fs.mkdirSync(cacheDir, { recursive: true })
  }

  const url = `https://github.com/Genymobile/scrcpy/releases/download/v${version}/scrcpy-server-v${version}`
  console.error(`[scrcpy] Downloading scrcpy-server v${version} from GitHub releases...`)

  try {
    const res = await fetch(url, { redirect: "follow" })
    if (!res.ok) {
      throw new Error(`HTTP ${res.status}: ${res.statusText}`)
    }
    const arrayBuffer = await res.arrayBuffer()
    const buffer = Buffer.from(arrayBuffer)
    if (buffer.length < 1024) {
      throw new Error(`File size unexpectedly small (${buffer.length} bytes)`)
    }
    fs.writeFileSync(cachePath, buffer)
    console.error(`[scrcpy] Downloaded scrcpy-server to ${cachePath}`)
    return cachePath
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : String(error)
    throw new Error(
      `scrcpy-server not found and automated download failed: ${message}. ` +
      `Please set SCRCPY_SERVER_PATH environment variable or check internet connection.`,
      { cause: error }
    )
  }
}

/**
 * Detect the installed scrcpy version.
 * If a bundled, cached, or runtime-updated server is used, returns the matching version.
 * Falls back to running `scrcpy --version` only for unversioned system servers.
 */
export function detectScrcpyVersion(serverPath?: string): string {
  const envVersion = process.env.SCRCPY_SERVER_VERSION
  if (envVersion) {
    return envVersion
  }

  const activeServerPath = serverPath || findScrcpyServer()
  if (activeServerPath) {
    const runtimeInfo = getRuntimeVersionInfo()
    if (runtimeInfo && activeServerPath === runtimeInfo.serverPath) {
      return runtimeInfo.version
    }

    const versionMatch = activeServerPath.match(/scrcpy-server-v(\d+\.\d+(?:\.\d+)?)/) ||
      activeServerPath.match(/v(\d+\.\d+(?:\.\d+)?)/)
    if (versionMatch) {
      return versionMatch[1]
    }

    const isBundledOrCached = getBundledServerPaths().includes(activeServerPath) ||
      activeServerPath.includes("vendor") ||
      activeServerPath.includes(".cache") ||
      activeServerPath.includes("scrcpy-cli")

    if (isBundledOrCached) {
      return SCRCPY_SERVER_VERSION
    }
  }

  try {
    const output = execSync("scrcpy --version 2>/dev/null", {
      timeout: 5000,
      encoding: "utf8",
    })
    const match = output.match(/scrcpy\s+(\d+\.\d+(?:\.\d+)?)/)
    if (match) {
      return match[1]
    }
  } catch {
    // scrcpy CLI not available, fall through
  }

  return SCRCPY_SERVER_VERSION
}

export function generateScid(): number {
  // Generate a random 31-bit positive integer (scrcpy uses hex format)
  return Math.floor(Math.random() * 0x7FFFFFFF) + 1
}

function getSocketName(scid: number): string {
  if (scid === -1) {
    return "scrcpy"
  }
  return `scrcpy_${scid.toString(16).padStart(8, "0")}`
}

export async function pushScrcpyServer(serial: string, serverPath: string): Promise<void> {
  await execAdb(["-s", serial, "push", serverPath, SCRCPY_SERVER_PATH_LOCAL], 30000)
}

export async function setupPortForwarding(
  serial: string,
  port: number,
  scid: number
): Promise<void> {
  const socketName = getSocketName(scid)
  await execAdb(
    ["-s", serial, "forward", `tcp:${port}`, `localabstract:${socketName}`]
  )
}

export async function removePortForwarding(serial: string, port: number): Promise<void> {
  try {
    await execAdb(["-s", serial, "forward", "--remove", `tcp:${port}`])
  } catch {
    // Ignore errors if forwarding doesn't exist
  }
}

export async function startScrcpyServer(
  serial: string,
  scid: number,
  options: ScrcpySessionOptions = {},
  serverPath?: string
): Promise<void> {
  const {
    maxSize = 0,
    maxFps = 0,
    videoBitRate = 0,
    videoEncoder,
  } = options

  const version = detectScrcpyVersion(serverPath)
  console.error(`[scrcpy] Using scrcpy server version: ${version}`)

  const serverArgs = [
    "-s", serial, "shell",
    `CLASSPATH=${SCRCPY_SERVER_PATH_LOCAL}`,
    "app_process",
    "/",
    "com.genymobile.scrcpy.Server",
    version,
    `scid=${scid.toString(16).padStart(8, "0")}`,
    `log_level=verbose`,
  ]

  if (maxSize > 0) {
    serverArgs.push(`max_size=${maxSize}`)
  }
  if (maxFps > 0) {
    serverArgs.push(`max_fps=${maxFps}`)
  }
  if (videoBitRate > 0) {
    serverArgs.push(`video_bit_rate=${videoBitRate}`)
  }
  if (videoEncoder) {
    serverArgs.push(`video_encoder=${videoEncoder}`)
  }

  serverArgs.push(
    "tunnel_forward=true",
    "audio=false"
  )

  return new Promise((resolve, reject) => {
    const child = spawn(getAdbPath(), serverArgs, {
      detached: true,
      stdio: ["ignore", "ignore", "pipe"],
      windowsHide: true,
    })

    if (child.stderr) {
      child.stderr.on("data", (data: Buffer) => {
        const msg = data.toString().trim()
        if (msg) {
          console.error(`[scrcpy-server] ${msg}`)
        }
      })
    }

    child.once("error", (err) => {
      reject(new Error(
        `Failed to start scrcpy server for ${serial}: ${err.message}`,
        { cause: err }
      ))
    })

    child.once("spawn", () => {
      child.unref()
      resolve()
    })
  })
}



// In forward tunnel mode, `adb forward` accepts TCP connections even when no
// server is listening behind the tunnel. To detect that the server is actually
// ready we read the dummy byte (sent by scrcpy with send_dummy_byte=true) after
// the TCP connection is established. If the read fails, the server is not ready.
export const connectAndVerify = async (port: number, timeout = 10000): Promise<net.Socket> =>
  new Promise((resolve, reject) => {
    const socket = net.createConnection({ port, host: "127.0.0.1" })
    let settled = false
    const timer = setTimeout(() => {
      if (settled) return
      settled = true
      socket.destroy()
      reject(new Error(`Connection timeout to port ${port}`))
    }, timeout)

    const fail = (err: Error) => {
      if (settled) return
      settled = true
      clearTimeout(timer)
      socket.destroy()
      reject(err)
    }

    socket.on("error", (err) => fail(
      new Error(`Socket error connecting to port ${port}`, { cause: err })
    ))

    socket.on("connect", () => {
      // TCP connected to the ADB tunnel. Now read the dummy byte to verify
      // the scrcpy server is actually listening behind the tunnel.
      socket.once("data", (chunk: Buffer) => {
        if (settled) return
        settled = true
        clearTimeout(timer)
        if (chunk.length > 1) {
          socket.unshift(chunk.subarray(1))
        }
        // Pause so data is buffered until the caller attaches its own handlers
        socket.pause()
        resolve(socket)
      })

      socket.once("close", () => fail(
        new Error("Socket closed before dummy byte received")
      ))
    })
  })

export const connectToServer = async (port: number, timeout = 10000): Promise<net.Socket> =>
  new Promise((resolve, reject) => {
    const socket = net.createConnection({ port, host: "127.0.0.1" })
    const timer = setTimeout(() => {
      socket.destroy()
      reject(new Error(`Connection timeout to port ${port}`))
    }, timeout)

    socket.on("connect", () => {
      clearTimeout(timer)
      resolve(socket)
    })

    socket.on("error", (err) => {
      clearTimeout(timer)
      reject(new Error(`Socket error connecting to port ${port}`, { cause: err }))
    })
  })
